// The item-name catalogues behind every `<input list=...>` picker, shared by the
// pages that have one (the solver page's goal rows, the timeline page's item
// box). Registers nothing at module scope, so any page may import it.
//
// Two catalogues, both generated by scripts/generate_items.py and checked in:
// mastery_items.txt (items that can actually be mastered -- what a mastery goal
// or a timeline is about) and items.txt (every known item across all data
// files, for plain item goals). Every picker still accepts a typed value absent
// from its list; the catalogue only supplies suggestions.
export const MASTERY_CATALOGUE = "/static/solverapp/mastery_items.txt";
export const ITEM_CATALOGUE = "/static/solverapp/items.txt";

// Fill a <datalist> with one <option> per line of `url`. Best-effort: a missing
// static file or a dropped network leaves the picker free-text, exactly as it
// behaves for a name the catalogue never had.
export async function loadCatalogue(url, datalistId) {
  try {
    const response = await fetch(url);
    if (!response.ok) return;
    const text = await response.text();
    const datalist = document.querySelector(`#${datalistId}`);
    if (!datalist) return;
    const fragment = document.createDocumentFragment();
    text
      .split("\n")
      .map((line) => line.trim())
      .filter(Boolean)
      .forEach((name) => {
        const option = document.createElement("option");
        option.value = name;
        fragment.appendChild(option);
      });
    datalist.appendChild(fragment);
  } catch (err) {
    // No network / no static file yet -- free-typing still works, just
    // without suggestions, same as any other best-effort enhancement here.
  }
}
